for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Looking at character-by-character changes
print("\nDetailed character analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"'{inp}' -> '{out}':")
    for j in range(max(len(inp), len(out))):
        if j < len(inp) and j < len(out):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(out):
            print(f"  Position {j}: (added) '{out[j]}'")

